using System;
using System.Collections.Generic;
using System.Linq;

public static class Words
{
    public static SortedDictionary<string, int> Count(string text)
    {
        var d = new SortedDictionary<string, int>();
        foreach (var w in text.ToLower().Split(' ', StringSplitOptions.RemoveEmptyEntries))
            d[w] = d.GetValueOrDefault(w) + 1;
        return d;
    }
}

