using System;
using System.Collections.Generic;
using System.Linq;

public static class Bag
{
    public static void Add(Dictionary<string, int> bag, string item, int n)
    {
        bag[item] = bag.GetValueOrDefault(item) + n;
    }

    public static int Take(Dictionary<string, int> bag, string item, int n)
    {
        int have = bag.GetValueOrDefault(item);
        int t = Math.Min(have, n);
        if (have - t <= 0) bag.Remove(item); else bag[item] = have - t;
        return t;
    }
}
